610  static int write_req_connect_first(void *_req, int is_end_stream)
   611  {
   612      struct st_h2o_http1_conn_t *conn = H2O_STRUCT_FROM_MEMBER(struct st_h2o_http1_conn_t, req, _req);
   613
   614      conn->req.write_req.cb = NULL; /* will not be called again until proceed_req is called by the generator */
   615      if (is_end_stream)
   616          conn->req.proceed_req = NULL;
   617
   618      return 0;
   619  }
