   621  static void handle_incoming_request(struct st_h2o_http1_conn_t *conn)
   622  {
   623      size_t inreqlen = conn->sock->input->size < H2O_MAX_REQLEN ? conn->sock->input->size : H2O_MAX_REQLEN;
   624      int reqlen, minor_version;
   625      struct phr_header headers[H2O_MAX_HEADERS];
   626      size_t num_headers = H2O_MAX_HEADERS;
   627      ssize_t entity_body_header_index;
   628      h2o_iovec_t expect;
   629
   630      if (conn->sock->input->size != 0)
   631          h2o_conn_set_state(&conn->super, H2O_CONN_STATE_ACTIVE);
   632
   633      /* need to set request_begin_at here for keep-alive connection */
   634      if (h2o_timeval_is_null(&conn->req.timestamps.request_begin_at))
   635          conn->req.timestamps.request_begin_at = h2o_gettimeofday(conn->super.ctx->loop);
   636
   637      reqlen = phr_parse_request(conn->sock->input->bytes, inreqlen, (const char **)&conn->req.input.method.base,
   638                                 &conn->req.input.method.len, (const char **)&conn->req.input.path.base, &conn->req.input.path.len,
   639                                 &minor_version, headers, &num_headers, conn->_prevreqlen);
   640      conn->_prevreqlen = inreqlen;
   641
   642      switch (reqlen) {
   643      default: { // parse complete
   644          conn->_unconsumed_request_size = reqlen;
   645          const char *err;
   646          if ((err = fixup_request(conn, headers, num_headers, minor_version, &expect, &entity_body_header_index)) != NULL &&
   647              err != fixup_request_is_h2_upgrade) {
   648              clear_timeouts(conn);
   649              send_bad_request(conn, err);
   650              return;
   651          }
   652          h2o_probe_log_request(&conn->req, conn->_req_index);
   653          if (err == fixup_request_is_h2_upgrade) {
   654              clear_timeouts(conn);
   655              h2o_socket_read_stop(conn->sock);
   656              if (h2o_http2_handle_upgrade(&conn->req, conn->super.connected_at) != 0)
   657                  h2o_send_error_400(&conn->req, "Invalid Request", "Broken upgrade request to HTTP/2", 0);
   658          } else if (entity_body_header_index != -1) {
   659              /* Request has body, start reading it. Invocation of `h2o_process_request` is delayed to reduce backend concurrency. */
   660              conn->req.timestamps.request_body_begin_at = h2o_gettimeofday(conn->super.ctx->loop);
   661              if (expect.base != NULL) {
   662                  if (!h2o_lcstris(expect.base, expect.len, H2O_STRLIT("100-continue"))) {
   663                      clear_timeouts(conn);
   664                      h2o_socket_read_stop(conn->sock);
   665                      h2o_send_error_417(&conn->req, "Expectation Failed", "unknown expectation",
   666                                         H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION);
   667                      return;
   668                  }
   669              }
   670              if (create_entity_reader(conn, headers + entity_body_header_index) != 0)
   671                  return;
   672              conn->req.write_req.cb = write_req_first;
   673              conn->req.write_req.ctx = &conn->req;
   674              conn->_unconsumed_request_size = 0;
   675              h2o_buffer_consume(&conn->sock->input, reqlen);
   676              h2o_buffer_init(&conn->req_body, &h2o_socket_buffer_prototype);
   677              if (expect.base != NULL) {
   678                  static const h2o_iovec_t res = {H2O_STRLIT("HTTP/1.1 100 Continue\r\n\r\n")};
   679                  h2o_socket_write(conn->sock, (void *)&res, 1, on_continue_sent);
   680                  /* processing of the incoming entity is postponed until the 100 response is sent */
   681                  h2o_socket_read_stop(conn->sock);
   682                  return;
   683              }
   684              conn->_req_entity_reader->handle_incoming_entity(conn);
   685          } else if (conn->req.is_tunnel_req) {
   686              /* Is a CONNECT request or a upgrade that uses our stream API (e.g., websocket tunnelling), therefore:
   687               * * the request is submitted immediately for processing,
   688               * * input is read and provided to the request handler using the request streaming API,
   689               * * but the timeout is stopped as the client might wait for the server to send 200 before sending anything. */
   690              clear_timeouts(conn);
   691              if (!h2o_req_can_stream_request(&conn->req) &&
   692                  h2o_memis(conn->req.input.method.base, conn->req.input.method.len, H2O_STRLIT("CONNECT"))) {
   693                  h2o_send_error_405(&conn->req, "Method Not Allowed", "Method Not Allowed", 0);
   694                  return;
   695              }
   696              if (create_content_length_entity_reader(conn, SIZE_MAX) != 0)
   697                  return;
   698              conn->_unconsumed_request_size = 0;
   699              h2o_buffer_consume(&conn->sock->input, reqlen);
   700              h2o_buffer_init(&conn->req_body, &h2o_socket_buffer_prototype);
   701              conn->req.write_req.cb = write_req_connect_first;
   702              conn->req.write_req.ctx = &conn->req;
   703              conn->req.proceed_req = proceed_request;
   704              conn->req.entity = h2o_iovec_init("", 0); /* set to non-NULL pointer to indicate that request body exists */
   705              h2o_process_request(&conn->req);
   706              conn->_req_entity_reader->handle_incoming_entity(conn);
   707          } else {
   708              /* Ordinary request without request body. */
   709              clear_timeouts(conn);
   710              h2o_socket_read_stop(conn->sock);
   711              h2o_process_request(&conn->req);
   712          }
   713      }
   714          return;
